    "4 Ekim Hayvanları Koruma Günü bağlamında hayvan çalışmalarında üç etik ilkeyi (kullanmama, sayıyı azaltma, acıyı hafifletme) ve insanlardan anket/görüşme verisi toplamak için gereken izin sürecini (25. hafta hazırlığı) konuş; kendi etik beyan maddelerini \"sınanacağı durum\" sütunuyla yaz."
