    "Şu dört kavramı ayır: (1) Veri uydurma (olmayan veriyi yazma), (2) Çarpıtma (veriyi veya grafiği seçerek/keserek farklı gösterme), (3) İntihal (başkasının cümlesini ya da fikrini — kendi cümlelerinle yeniden yazsan bile! — kaynak göstermeden kullanma), (4) Haksız yazarlık (katkı yapmayanı eklemek veya katkı yapanı çıkarmak).",
